#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\n' > "$t"
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10:30 x >/dev/null || { echo "book failed"; fail=1; }
grep -q '^# room' "$t" && grep -q '^aoi.2026-01-05.09:00.10:30.x$' "$t" || { echo "booking not appended"; fail=1; }
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 10:00 11:00 y >/dev/null 2>&1; [ $? = 1 ] || { echo "overlap should exit 1"; fail=1; }
rm -f "$t"; exit $fail

spec/capacity.spec.sh.text:
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n' > "$t"
b() { BOOKINGS=$t bash src/book.sh "$@" >/dev/null 2>&1; }
b aoi 2026-01-05 09:00 10:00 x 4 || { echo "4 people in aoi rejected"; fail=1; }
b aoi 2026-01-05 10:00 11:00 y 5; [ $? = 1 ] || { echo "5 people in aoi should exit 1"; fail=1; }
b aoi 2026-01-05 12:00 13:00 z many; [ $? = 2 ] || { echo "a non-number should exit 2"; fail=1; }
b momiji 2026-01-05 10:00 11:00 z; [ $? = 2 ] || { echo "unknown room should exit 2"; fail=1; }
r=$(mktemp); printf '# room\tcapacity\nsolo\t1\nzero\t0\n' > "$r"
BOOKINGS=$t ROOMS=$r bash src/book.sh zero 2026-01-05 09:00 10:00 x >/dev/null 2>&1; [ $? = 1 ] || { echo "omitted people in a 0-capacity room should exit 1 (counts as 1)"; fail=1; }
BOOKINGS=$t ROOMS=$r bash src/book.sh solo 2026-01-05 09:00 10:00 x >/dev/null 2>&1; [ $? = 0 ] || { echo "omitted people in a 1-capacity room should be accepted (counts as 1)"; fail=1; }
rm -f "$r" "$t"; exit $fail

